rtl:
always_comb begin
  case (state)
    3'h0: next_state = 3'h1;
    3'h1: next_state = 3'h2;
    3'h2: next_state = 3'h0;
    // States 3-7 unhandled — FSM freezes
  endcase
end

fix_replacement:
always_comb begin
  case (state)
    3'h0: next_state = 3'h1;
    3'h1: next_state = 3'h2;
    3'h2: next_state = 3'h0;
    default: next_state = 3'h0;  // Escape illegal states
  endcase
end
